/* ------------------------------------------------------------------------
 * High-level helpers
 * ------------------------------------------------------------------------ */

export type KindType = "manual" | "automated" | "mixed";

// 1:1 with frontend state-icon.hbs — bg + text color tile, inline 16px.
const TYPE_CLASS: Record<KindType, string> = {
  manual: "bg-type-manual text-type-manual-foreground",
  automated: "bg-type-automated text-type-automated-foreground",
  mixed: "bg-type-mixed text-type-mixed-foreground",
};

const TYPE_LABEL: Record<KindType, string> = {
  manual: "Manual",
  automated: "Automated",
  mixed: "Mixed",
};

/**
 * Colored square tile containing the manual / automated / mixed icon.
 * Matches frontend's `state-icon.hbs` — `inline h-4 w-4` inside a padded
 * box, using the semantic `--color-type-*` tokens.
 */
export function TypeIcon({
  type,
  className,
  title,
}: {
  type: KindType;
  className?: string;
  title?: string;
}) {
  const Glyph =
    type === "manual"
      ? ManualGlyph
      : type === "automated"
        ? AutomatedGlyph
        : MixedGlyph;
  return (
    <span
      title={title ?? TYPE_LABEL[type]}
      className={cn(
        "inline-flex h-5 w-5 items-center justify-center rounded",
        TYPE_CLASS[type],
        className
      )}
    >
      <Glyph className="h-3.5 w-3.5" />
    </span>
  );
}

/**
 * Resolves Testomat.io's various "kind/state/automated" signals to a
 * single `manual | automated | mixed` bucket. Returns `null` when the
 * entity has no meaningful hint.
 */
export function resolveType(entity: {
  kind?: string | null;
  state?: string | null;
  automated?: boolean | null;
}): KindType | null {
  const raw = (entity.kind ?? entity.state ?? "").toLowerCase();
  if (raw === "manual") return "manual";
  if (raw === "automated") return "automated";
  if (raw === "mixed") return "mixed";
  if (entity.automated === true) return "automated";
  if (entity.automated === false) return "manual";
  return null;
}

/* ---- Suite kind (folder / file / root-folder) ------------------------ */

/**
 * Folder/file icon matching the frontend's `.folder-icon` / `.suite-icon`
 * helpers. Uses `--folder-icon-fill-{1,2}` for the two-tone folder fill
 * so light and dark modes keep the same inner/outer contrast.
 */
export function SuiteKindIcon({
  fileType,
  isRoot,
  className,
  style,
}: {
  fileType?: "file" | "folder" | null;
  isRoot?: boolean;
  className?: string;
  style?: React.CSSProperties;
}) {
  // Colour vars mirror badge.scss:
  //   light: fill-1 #525252 / fill-2 #0a0a0a
  //   dark:  fill-1 rgba(255,255,255,0.6) / fill-2 rgba(255,255,255,0.9)
  const folderStyle: React.CSSProperties = {
    ["--folder-icon-fill-1" as string]:
      "color-mix(in srgb, var(--muted-foreground) 100%, transparent)",
    ["--folder-icon-fill-2" as string]:
      "color-mix(in srgb, var(--foreground) 100%, transparent)",
    ...(style ?? {}),
  };

  if (fileType === "folder") {
    const Glyph = isRoot ? FolderRootGlyph : FolderGlyph;
    return (
      <Glyph
        className={cn("inline h-5 w-5 shrink-0", className)}
        style={folderStyle}
      />
    );
  }
  // Suite / file leaf
  return (
    <SuiteGlyph
      className={cn(
        "inline h-5 w-5 shrink-0 text-muted-foreground",
        className
      )}
    />
  );
}
